-- Root-only reviewed metadata correction. Caller transaction commits or rolls back.
DO $provider_class$
DECLARE a population_top3000_202608_202609_v1.acquisition_control%rowtype;p population_top3000_202608_202609_v1.pipeline_control%rowtype;b population_top3000_202608_202609_v1.pipeline_adapter%rowtype;before_counts jsonb;after_counts jsonb;v_review jsonb;v_actual jsonb;wrapper_hash text;edge_count bigint;released jsonb;BEGIN
 PERFORM pg_advisory_xact_lock(2026083000261022);
 SELECT * INTO STRICT a FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton FOR UPDATE;
 SELECT * INTO STRICT p FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton FOR UPDATE;
 IF a.owner_id IS DISTINCT FROM 'top3000-completion-20261024-root-5db48b32d103' OR a.owner_fence IS DISTINCT FROM 3 OR a.stop_generation IS DISTINCT FROM 1 OR a.enabled IS DISTINCT FROM true OR a.stopped IS DISTINCT FROM false OR a.hold_reason IS NOT NULL OR p.enabled IS DISTINCT FROM true OR p.expected_owner_id IS DISTINCT FROM a.owner_id OR p.expected_owner_fence IS DISTINCT FROM a.owner_fence OR p.expected_stop_generation IS DISTINCT FROM a.stop_generation OR a.admitted_until IS NULL OR a.admitted_until<=clock_timestamp() OR p.deadline IS NULL OR p.deadline<=clock_timestamp() OR a.scope_sha256 IS DISTINCT FROM '8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd' OR p.scope_sha256 IS DISTINCT FROM a.scope_sha256 OR p.budget_evidence#>>'{monetary_policy,authority_event_id}' IS DISTINCT FROM '9528' THEN RAISE EXCEPTION 'CTX07_PROVIDER_CLASS_AUTHORITY';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE family_id='CTX07' AND stage='ACQUIRE' AND status='LEASED') THEN RAISE EXCEPTION 'CTX07_PROVIDER_CLASS_ACTIVE';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease l JOIN population_top3000_202608_202609_v1.pipeline_attempt z USING(attempt_id) JOIN population_top3000_202608_202609_v1.pipeline_task t USING(task_id) WHERE t.family_id='CTX07' AND t.stage='ACQUIRE' AND l.released_at IS NULL) THEN RAISE EXCEPTION 'CTX07_EDGE_UNRECONCILED_PROVIDER_LEASE';END IF;
 -- Retained legacy sources never change executor or resource semantics during unfinished work.
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE family_id='CTX07' AND stage='ACQUIRE' AND payload->>'kind' IS DISTINCT FROM 'CTX07_SOURCE_RECOVERY_V6' AND status<>'COMPLETE') THEN RAISE EXCEPTION 'CTX07_PROVIDER_CLASS_LEGACY_PENDING';END IF;
 SELECT * INTO STRICT b FROM population_top3000_202608_202609_v1.pipeline_adapter WHERE family_id='CTX07' AND stage='ACQUIRE' FOR UPDATE;
 IF b.resource_class IS DISTINCT FROM 'DATABASE' OR b.producer_revision IS DISTINCT FROM 'ctx07-recovery-v6' OR b.function_sha256 IS DISTINCT FROM '4c7825d47bb26401b3f75f5c450c7727f7cc32654fe97ede71a64244126a2c7b' OR b.function_sha256 IS DISTINCT FROM encode(sha256(convert_to(pg_get_functiondef(b.function_oid),'UTF8')),'hex') OR population_top3000_202608_202609_v1.ctx07_recovery_bundle_v6() IS DISTINCT FROM '0d2aa25a50603da0fc5f00bf4eea5419fe56f368244cef73de08c21ea70dbe4f' THEN RAISE EXCEPTION 'CTX07_PROVIDER_CLASS_PREIMAGE';END IF;
 wrapper_hash:=encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx07_recovery_acquire_v7(uuid,text)'::regprocedure),'UTF8')),'hex');
 SELECT details INTO v_review FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='CTX07_V7_EDGE_INDEPENDENT_REVIEW' AND details->>'adapter_sha256'=b.function_sha256 ORDER BY event_id DESC LIMIT 1;
 IF v_review->>'wrapper_sha256' IS DISTINCT FROM wrapper_hash OR v_review->>'maximum_cumulative_edge_invocations' IS DISTINCT FROM '114' OR v_review->>'approved' IS DISTINCT FROM 'true' OR nullif(v_review->>'reviewer','') IS NULL OR v_review->>'reviewer' IS NOT DISTINCT FROM v_review->>'producer' THEN RAISE EXCEPTION 'CTX07_PROVIDER_CLASS_REVIEW_REQUIRED';END IF;
 SELECT details INTO v_actual FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='CTX07_V7_EDGE_ACTUAL_ROLLBACK' AND details->>'wrapper_sha256'=wrapper_hash ORDER BY event_id DESC LIMIT 1;
 IF v_actual->>'result' IS DISTINCT FROM 'PASS_CTX07_V7_EDGE_GUARD' OR v_actual->>'production_changes_rolled_back' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'CTX07_EDGE_ACTUAL_ROLLBACK_REQUIRED';END IF;
 SELECT count(*) INTO edge_count FROM population_top3000_202608_202609_v1.pipeline_attempt z JOIN population_top3000_202608_202609_v1.pipeline_task q USING(task_id) WHERE q.payload->>'kind'='CTX07_SOURCE_RECOVERY_V6' AND z.request_id IS NOT NULL;
 IF edge_count>=114 THEN RAISE EXCEPTION 'CTX07_EDGE_NEW_ADMISSION_ALREADY_EXHAUSTED';END IF;
 before_counts:=jsonb_build_object('provider_requests',a.provider_requests,'http_invocations',a.http_invocations,'stored_bytes',a.stored_bytes,'reserved_bytes',a.reserved_bytes,'dispatch_calls',a.dispatch_calls,'deadline',p.deadline,'admitted_until',a.admitted_until);
 UPDATE population_top3000_202608_202609_v1.pipeline_adapter SET resource_class='PROVIDER',function_oid='population_top3000_202608_202609_v1.ctx07_recovery_acquire_v7(uuid,text)'::regprocedure,function_sha256=wrapper_hash,producer_revision='ctx07-recovery-edge-v7',reviewed_test_evidence=coalesce(reviewed_test_evidence,'{}'::jsonb)||jsonb_build_object('edge_guard_review_v7',v_review,'edge_guard_rollback_v7',v_actual) WHERE family_id='CTX07' AND stage='ACQUIRE';
 SELECT jsonb_build_object('provider_requests',c.provider_requests,'http_invocations',c.http_invocations,'stored_bytes',c.stored_bytes,'reserved_bytes',c.reserved_bytes,'dispatch_calls',c.dispatch_calls,'deadline',d.deadline,'admitted_until',c.admitted_until) INTO after_counts FROM population_top3000_202608_202609_v1.acquisition_control c CROSS JOIN population_top3000_202608_202609_v1.pipeline_control d WHERE c.singleton AND d.singleton;
 IF after_counts IS DISTINCT FROM before_counts THEN RAISE EXCEPTION 'CTX07_PROVIDER_CLASS_COUNTER_CHANGED';END IF;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CTX07_V7_EDGE_ADMISSION',jsonb_build_object('owner_id',a.owner_id,'owner_fence',3,'stop_generation',1,'scope_sha256',a.scope_sha256,'authority_event_id',9528,'original_edge_cap',64,'additional_edge_allowance',50,'maximum_cumulative_edge_invocations',114,'cumulative_edge_invocations_preserved',edge_count,'original64edge_overrun_receipt_event',18490,'provider_request_cap_unchanged',64,'original_deadline',p.deadline,'not_after',least(a.admitted_until,p.deadline,(SELECT min(not_after) FROM population_top3000_202608_202609_v1.ctx07_recovery_request_v6)),'wrapper_sha256',wrapper_hash,'review',v_review,'actual_runtime_test',v_actual));
 WITH named AS(SELECT (x->>'task_id')::uuid id FROM population_top3000_202608_202609_v1.pipeline_event e CROSS JOIN LATERAL jsonb_array_elements(e.details->'tasks')x WHERE e.event_id=18402 AND e.event='CTX07_V6_EDGE_ADMISSION_REVIEW_HOLD'), changed AS(
 UPDATE population_top3000_202608_202609_v1.pipeline_task t SET status='READY',blocker_code=NULL,blocker_until=NULL,not_before=clock_timestamp(),resumption_condition=coalesce(resumption_condition,'{}'::jsonb)||jsonb_build_object('reviewed_edge_cap',114,'pause_receipt_event',18402) WHERE t.task_id IN(SELECT id FROM named) AND t.status='BLOCKED' AND t.lease_until IS NULL AND EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_attempt patt WHERE patt.attempt_id=t.attempt_id AND patt.ended_at IS NOT NULL AND patt.outcome<>'RUNNING') AND NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease l JOIN population_top3000_202608_202609_v1.pipeline_attempt patt USING(attempt_id) WHERE patt.task_id=t.task_id AND l.released_at IS NULL) AND t.blocker_code='CTX07_V6_EDGE_ADMISSION_REVIEW' AND t.payload->>'kind'='CTX07_SOURCE_RECOVERY_V6' AND t.stage='ACQUIRE' RETURNING t.task_id,t.executions,t.cumulative_failures,t.checkpoint)
 SELECT coalesce(jsonb_agg(to_jsonb(changed)),'[]') INTO released FROM changed;
 WITH changed AS(UPDATE population_top3000_202608_202609_v1.pipeline_task t SET status='READY',blocker_code=NULL,blocker_until=NULL,not_before=greatest(clock_timestamp(),(resumption_condition->>'not_before')::timestamptz),resumption_condition=coalesce(resumption_condition,'{}'::jsonb)||jsonb_build_object('reviewed_provider_scheduling',true) WHERE t.task_id IN('e7a63348-8c95-46dc-aa84-3bfa51262b13','903e40ae-d592-4f69-8bd4-ba37715cc761') AND t.status='BLOCKED' AND t.lease_until IS NULL AND EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_attempt patt WHERE patt.attempt_id=t.attempt_id AND patt.ended_at IS NOT NULL AND patt.outcome<>'RUNNING') AND NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease l JOIN population_top3000_202608_202609_v1.pipeline_attempt patt USING(attempt_id) WHERE patt.task_id=t.task_id AND l.released_at IS NULL) AND t.blocker_code='DEPENDENCY_PENDING' AND t.resumption_condition->>'state'='WAIT' AND t.payload->>'kind'='CTX07_SOURCE_RECOVERY_V6' AND t.stage='ACQUIRE' AND NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease l WHERE l.attempt_id=t.attempt_id) RETURNING t.task_id,t.executions,t.cumulative_failures,t.checkpoint)
 SELECT released||coalesce(jsonb_agg(to_jsonb(changed)),'[]') INTO released FROM changed;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CTX07_V7_EDGE_GUARD_INTEGRATED',jsonb_build_object('owner_id',a.owner_id,'owner_fence',3,'stop_generation',1,'scope_sha256',a.scope_sha256,'adapter_sha256',b.function_sha256,'bundle_sha256',population_top3000_202608_202609_v1.ctx07_recovery_bundle_v6(),'old_resource_class','DATABASE','new_resource_class','PROVIDER','counters',after_counts,'released_tasks',released,'source_tasks_changed',jsonb_array_length(released),'new_adapter_sha256',wrapper_hash,'source_evidence_changed',0,'useful_output_claimed',false));
 PERFORM population_top3000_202608_202609_v1.pipeline_wake_v1(a.owner_id,a.owner_fence,'Reviewed CTX07 local edge cap114 and provider dispatch classification');
END;$provider_class$;
